1	import { canonicalize, sha256 } from './canonicalize.ts';
2	
3	export const UNRESOLVED_REASONS = [
4		'unparsed-file',
5		'unsupported-language',
6		'unsupported-syntax',
7		'unresolved-specifier',
8		'external-module-boundary',
9		'builtin-module-boundary',
10		'linked-set-boundary',
11		'unresolved-symbol',
12		'ambiguous-definition',
13		'dynamic-member-access',
14		'computed-property-key',
15		'string-keyed-lookup',
16		'property-alias-write-uncertain',
17		'higher-order-call-boundary',
18		'stale-snapshot',
19		// A supplied input whose own import/re-export specifier failed to link to
20		// another supplied input: the file could not be established as part of the
21		// traversed graph, so no traversal answer may claim to have covered it.
22		'unlinked-input',
23	] as const;
24	
25	export type UnresolvedReason = (typeof UNRESOLVED_REASONS)[number];
26	
27	export interface SymbolAnchor {
28		readonly schema: 'guessless.symbol-anchor/v1';
29		readonly file: string;
30		readonly semanticPath: readonly string[];
31		readonly fingerprint: string;
32	}
33	
34	export interface UnresolvedSite {
35		readonly site: SymbolAnchor;
36		readonly reason: UnresolvedReason;
37		readonly detail: string;
38	}
39	
40	export const SAFE_CHANGE_ROLES = [
41		'declaration',
42		'reference',
43		'read',
44		'write',
45		'read-write',
46		'call',
47		'import',
48		'export',
49		'alias',
50		'namespace',
51		'barrel',
52		'witness',
53	] as const;
54	
55	export type SafeChangeRole = (typeof SAFE_CHANGE_ROLES)[number];
56	export type SafeChangeIntent = 'rename' | 'delete' | 'entry-point';
57	export interface SafeChangeBindingSelector {
58		readonly file: string;
59		readonly name: string;
60		readonly space: 'value' | 'type' | 'namespace' | 'typeof' | 'any';
61		readonly from?: SymbolAnchor;
62	}
63	export type SafeChangeTarget = SymbolAnchor | SafeChangeBindingSelector;
64	
65	export interface SafeChangeImpactResult {
66		readonly site: SymbolAnchor;
67		readonly roles: readonly SafeChangeRole[];
68		readonly witness: readonly SymbolAnchor[];
69	}
70	
71	export type QueryRequest =
72		| { readonly kind: 'addFile'; readonly file: string }
73		| {
74				readonly kind:
75					| 'definitionOf'
76					| 'referencesOf'
77					| 'readsOf'
78					| 'writesOf'
79					| 'capturesOf'
80					| 'reachableFrom'
81					| 'reaches';
82				readonly target: SymbolAnchor;
83		  }
84		| { readonly kind: 'exportedNames'; readonly file: string }
85		| {
86				readonly kind: 'resolveBinding';
87				readonly file: string;
88				readonly name: string;
89				readonly space: 'value' | 'type' | 'namespace' | 'typeof' | 'any';
90				readonly scope: SymbolAnchor | null;
91		  }
92		| {
93				readonly kind: 'safeChangeImpact';
94				readonly snapshot: string;
95				readonly intent: SafeChangeIntent;
96				readonly target: SafeChangeTarget;
97		  };
98	
99	interface ReceiptBase<T> {
100		readonly schema: 'guessless.receipt/v1';
101		readonly query: string;
102		readonly request: QueryRequest;
103		readonly snapshot: string;
104		readonly results: readonly T[];
105		readonly integrity: string;
106	}
107	
108	export interface CompleteReceipt<T> extends ReceiptBase<T> {
109		readonly state: 'complete';
110	}
111	export interface PartialReceipt<T> extends ReceiptBase<T> {
112		readonly state: 'partial';
113		readonly unresolved: readonly UnresolvedSite[];
114	}
115	export interface RefusedReceipt<T> extends ReceiptBase<T> {
116		readonly state: 'refused';
117		readonly reason: UnresolvedReason;
118		readonly detail: string;
119	}
120	export type Receipt<T> = CompleteReceipt<T> | PartialReceipt<T> | RefusedReceipt<T>;
121	type WithoutIntegrity<T> = T extends unknown ? Omit<T, 'integrity'> : never;
122	type UnsignedReceipt<T> = WithoutIntegrity<Receipt<T>>;
123	
124	const baseKeys = ['query', 'request', 'results', 'schema', 'snapshot', 'state'] as const;
125	const anchorKeys = ['file', 'fingerprint', 'schema', 'semanticPath'] as const;
126	
127	export function makeReceipt<T>(receipt: UnsignedReceipt<T>): Receipt<T> {
128		assertReceiptShape(receipt);
129		return { ...receipt, integrity: sha256(receipt) } as Receipt<T>;
130	}
131	
132	export function verifyReceipt(value: unknown, currentSnapshot?: string): value is Receipt<unknown> {
133		try {
134			assertReceiptShape(value);
135			const record = value as Record<string, unknown>;
136			if (typeof record.integrity !== 'string' || !/^[a-f0-9]{64}$/.test(record.integrity))
137				return false;
138			if (currentSnapshot !== undefined && record.snapshot !== currentSnapshot) return false;
139			const { integrity, ...unsigned } = record;
140			return integrity === sha256(unsigned);
141		} catch {
142			return false;
143		}
144	}
145	
146	function exactKeys(record: Record<string, unknown>, extras: readonly string[]): void {
147		const expected = [
148			...baseKeys,
149			...extras,
150			...('integrity' in record ? ['integrity'] : []),
151		].sort();
152		const actual = Object.keys(record).sort();
153		if (actual.join('\u0000') !== expected.join('\u0000'))
154			throw new TypeError('receipt state has invalid or cross-state fields');
155	}
156	
157	function assertReceiptShape(value: unknown): void {
158		if (!isRecord(value) || Array.isArray(value))
159			throw new TypeError('receipt must be an object, never a bare list');
160		const record = value;
161		if (
162			record.schema !== 'guessless.receipt/v1' ||
163			typeof record.query !== 'string' ||
164			!Array.isArray(record.results) ||
165			typeof record.snapshot !== 'string' ||
166			!/^[a-f0-9]{64}$/.test(record.snapshot)
167		)
168			throw new TypeError('invalid receipt envelope');
169		assertRequest(record.query, record.request);
170		if (record.state === 'complete') exactKeys(record, []);
171		else if (record.state === 'partial') {
172			exactKeys(record, ['unresolved']);
173			if (!Array.isArray(record.unresolved) || record.unresolved.length === 0)
174				throw new TypeError('partial receipt needs unresolved sites');
175			for (const item of record.unresolved) assertUnresolved(item);
176		} else if (record.state === 'refused') {
177			exactKeys(record, ['detail', 'reason']);
178			if (
179				record.results.length !== 0 ||
180				!isReason(record.reason) ||
181				typeof record.detail !== 'string'
182			)
183				throw new TypeError('invalid refused receipt');
184		} else throw new TypeError('receipt state must be complete, partial, or refused');
185		assertQueryResults(record.query, record.results);
186	}
187	
188	function assertRequest(query: string, value: unknown): asserts value is QueryRequest {
189		if (!isRecord(value) || value.kind !== query)
190			throw new TypeError('receipt request must match query');
191		if (query === 'addFile' || query === 'exportedNames') {
192			if (!hasExactKeys(value, ['file', 'kind']) || typeof value.file !== 'string')
193				throw new TypeError(`invalid ${query} request`);
194			return;
195		}
196		if (
197			[
198				'definitionOf',
199				'referencesOf',
200				'readsOf',
201				'writesOf',
202				'capturesOf',
203				'reachableFrom',
204				'reaches',
205			].includes(query)
206		) {
207			if (!hasExactKeys(value, ['kind', 'target']) || !isAnchor(value.target))
208				throw new TypeError(`invalid ${query} request`);
209			return;
210		}
211		if (query === 'resolveBinding') {
212			if (
213				!hasExactKeys(value, ['file', 'kind', 'name', 'scope', 'space']) ||
214				typeof value.file !== 'string' ||
215				typeof value.name !== 'string' ||
216				!['value', 'type', 'namespace', 'typeof', 'any'].includes(String(value.space)) ||
217				(value.scope !== null && !isAnchor(value.scope))
218			)
219				throw new TypeError('invalid resolveBinding request');
220			return;
221		}
222		if (query === 'safeChangeImpact') {
223			if (
224				!hasExactKeys(value, ['intent', 'kind', 'snapshot', 'target']) ||
225				typeof value.snapshot !== 'string' ||
226				!/^[a-f0-9]{64}$/.test(value.snapshot) ||
227				!['rename', 'delete', 'entry-point'].includes(String(value.intent)) ||
228				(!isAnchor(value.target) && !isSafeChangeBindingSelector(value.target))
229			)
230				throw new TypeError('invalid safeChangeImpact request');
231			return;
232		}
233		throw new TypeError(`unknown receipt query '${query}'`);
234	}
235	
236	function assertQueryResults(query: string, results: unknown[]): void {
237		if (query === 'addFile') {
238			if (results.length !== 0) throw new TypeError('addFile refusal cannot have results');
239			return;
240		}
241		if (query === 'definitionOf' || query === 'resolveBinding') {
242			if (results.length > 1 || !results.every(isAnchor))
243				throw new TypeError(`${query} requires at most one anchor result`);
244			return;
245		}
246		if (query === 'referencesOf' || query === 'readsOf' || query === 'writesOf') {
247			for (const result of results) {
248				if (
249					!isRecord(result) ||
250					!hasExactKeys(result, ['access', 'site']) ||
251					!isAnchor(result.site) ||
252					!['read', 'write', 'read-write'].includes(String(result.access))
253				)
254					throw new TypeError('invalid reference result');
255				if (query === 'readsOf' && result.access === 'write')
256					throw new TypeError('readsOf contains a write-only result');
257				if (query === 'writesOf' && result.access === 'read')
258					throw new TypeError('writesOf contains a read-only result');
259			}
260			return;
261		}
262		if (query === 'exportedNames') {
263			for (const result of results)
264				if (
265					!isRecord(result) ||
266					!hasExactKeys(result, ['module', 'name']) ||
267					!isAnchor(result.module) ||
268					typeof result.name !== 'string'
269				)
270					throw new TypeError('invalid export result');
271			return;
272		}
273		if (query === 'capturesOf') {
274			for (const result of results)
275				if (
276					!isRecord(result) ||
277					!hasExactKeys(result, ['isWritten', 'references', 'symbol']) ||
278					!isAnchor(result.symbol) ||
279					!Array.isArray(result.references) ||
280					!result.references.every(isAnchor) ||
281					typeof result.isWritten !== 'boolean'
282				)
283					throw new TypeError('invalid capture result');
284			return;
285		}
286		if (query === 'reachableFrom' || query === 'reaches') {
287			const symbols = new Set<string>();
288			for (const result of results) {
289				if (
290					!isRecord(result) ||
291					!hasExactKeys(result, ['symbol', 'witness']) ||
292					!isAnchor(result.symbol) ||
293					!Array.isArray(result.witness) ||
294					result.witness.length === 0 ||
295					!result.witness.every(isAnchor)
296				)
297					throw new TypeError('invalid reachability result');
298				const identity = canonicalize(result.symbol);
299				if (symbols.has(identity)) throw new TypeError('duplicate reachability result');
300				symbols.add(identity);
301			}
302			return;
303		}
304		if (query === 'safeChangeImpact') {
305			const sites = new Set<string>();
306			for (const result of results) {
307				if (
308					!isRecord(result) ||
309					!hasExactKeys(result, ['roles', 'site', 'witness']) ||
310					!isAnchor(result.site) ||
311					!Array.isArray(result.roles) ||
312					result.roles.length === 0 ||
313					!result.roles.every(isSafeChangeRole) ||
314					new Set(result.roles).size !== result.roles.length ||
315					!Array.isArray(result.witness) ||
316					!result.witness.every(isAnchor)
317				)
318					throw new TypeError('invalid safe-change impact result');
319				const identity = canonicalize(result.site);
320				if (sites.has(identity)) throw new TypeError('duplicate safe-change impact site');
321				sites.add(identity);
322			}
323			return;
324		}
325		throw new TypeError(`unknown receipt query '${query}'`);
326	}
327	
328	function assertUnresolved(value: unknown): void {
329		if (
330			!isRecord(value) ||
331			!hasExactKeys(value, ['detail', 'reason', 'site']) ||
332			!isAnchor(value.site) ||
333			!isReason(value.reason) ||
334			typeof value.detail !== 'string'
335		)
336			throw new TypeError('invalid unresolved site');
337	}
338	function isReason(value: unknown): value is UnresolvedReason {
339		return typeof value === 'string' && (UNRESOLVED_REASONS as readonly string[]).includes(value);
340	}
341	function isSafeChangeRole(value: unknown): value is SafeChangeRole {
342		return typeof value === 'string' && (SAFE_CHANGE_ROLES as readonly string[]).includes(value);
343	}
344	function isSafeChangeBindingSelector(value: unknown): value is SafeChangeBindingSelector {
345		if (!isRecord(value)) return false;
346		const keys =
347			value.from === undefined ? ['file', 'name', 'space'] : ['file', 'from', 'name', 'space'];
348		return (
349			hasExactKeys(value, keys) &&
350			typeof value.file === 'string' &&
351			typeof value.name === 'string' &&
352			['value', 'type', 'namespace', 'typeof', 'any'].includes(String(value.space)) &&
353			(value.from === undefined || isAnchor(value.from))
354		);
355	}
356	function isRecord(value: unknown): value is Record<string, unknown> {
357		return value !== null && typeof value === 'object' && !Array.isArray(value);
358	}
359	function hasExactKeys(record: Record<string, unknown>, keys: readonly string[]): boolean {
360		return Object.keys(record).sort().join('\u0000') === [...keys].sort().join('\u0000');
361	}
362	
363	export function isAnchor(value: unknown): value is SymbolAnchor {
364		if (!isRecord(value) || !hasExactKeys(value, anchorKeys)) return false;
365		return (
366			value.schema === 'guessless.symbol-anchor/v1' &&
367			typeof value.file === 'string' &&
368			Array.isArray(value.semanticPath) &&
369			value.semanticPath.length > 0 &&
370			value.semanticPath.every((part) => typeof part === 'string') &&
371			typeof value.fingerprint === 'string' &&
372			/^[a-f0-9]{64}$/.test(value.fingerprint)
373		);
374	}
375	
376	export function receiptCanonicalForm(receipt: Receipt<unknown>): string {
377		return canonicalize(receipt);
378	}
