1	import type { Analyzer, Module, Reference, Scope, Space, Symbol } from 'yuku-analyzer';
2	import { anchorSite, anchorSymbol, resolveSymbolAnchor } from './anchors.ts';
3	import {
4		makeReceipt,
5		type QueryRequest,
6		type Receipt,
7		type SymbolAnchor,
8		type UnresolvedSite,
9	} from './contracts.ts';
10	import {
11		boundaryDetail,
12		boundaryReason,
13		suppliedInputIndex,
14		unlinkedInputSites,
15	} from './linking.ts';
16	import { analyzerSnapshot } from './snapshot.ts';
17	
18	export interface ReferenceResult {
19		readonly site: SymbolAnchor;
20		readonly access: 'read' | 'write' | 'read-write';
21	}
22	export interface CaptureResult {
23		readonly symbol: SymbolAnchor;
24		readonly references: readonly SymbolAnchor[];
25		readonly isWritten: boolean;
26	}
27	export interface ExportResult {
28		readonly name: string;
29		readonly module: SymbolAnchor;
30	}
31	
32	type YukuNode = Parameters<Module['symbolOf']>[0];
33	type RichNode = YukuNode & {
34		type: string;
35		operator?: string;
36		left?: YukuNode;
37		right?: YukuNode;
38		object?: YukuNode;
39		property?: YukuNode;
40		computed?: boolean;
41		value?: unknown;
42		id?: YukuNode;
43		init?: YukuNode;
44		expression?: YukuNode;
45		expressions?: YukuNode[];
46		argument?: YukuNode;
47		arguments?: YukuNode[];
48		consequent?: YukuNode;
49		alternate?: YukuNode;
50		key?: YukuNode;
51		name?: string;
52		properties?: YukuNode[];
53		elements?: Array<YukuNode | null>;
54		quasi?: YukuNode;
55	};
56	
57	const transparentExpressions = new Set([
58		'ParenthesizedExpression',
59		'TSAsExpression',
60		'TSTypeAssertion',
61		'TSSatisfiesExpression',
62		'TSNonNullExpression',
63	]);
64	
65	function expressionAccess(
66		module: Module,
67		node: YukuNode,
68		fallback: ReferenceResult['access'] = 'read',
69	): ReferenceResult['access'] {
70		let current: YukuNode = node;
71		while (true) {
72			const parent = module.parentOf(current) as RichNode | null;
73			if (parent === null) return fallback;
74			if (parent.type === 'UpdateExpression') return 'read-write';
75			if (parent.type === 'UnaryExpression' && parent.operator === 'delete') return 'write';
76			if (
77				parent.type === 'AssignmentExpression' &&
78				parent.left !== undefined &&
79				isWithin(module, node, parent.left)
80			)
81				return parent.operator === '=' ? 'write' : 'read-write';
82			if (
83				(parent.type === 'ForInStatement' || parent.type === 'ForOfStatement') &&
84				parent.left !== undefined &&
85				isWithin(module, node, parent.left)
86			)
87				return 'write';
88			if (
89				[
90					'ExpressionStatement',
91					'ReturnStatement',
92					'CallExpression',
93					'FunctionDeclaration',
94					'FunctionExpression',
95					'ArrowFunctionExpression',
96					'Program',
97				].includes(parent.type)
98			)
99				return fallback;
100			current = parent;
101		}
102	}
103	
104	function referenceAccess(reference: Reference): ReferenceResult['access'] {
105		return reference.isWrite ? expressionAccess(reference.module, reference.node, 'write') : 'read';
106	}
107	
108	function uniqueUnresolved(items: UnresolvedSite[]): UnresolvedSite[] {
109		const seen = new Set<string>();
110		return items
111			.filter((item) => {
112				const key = `${item.reason}:${item.site.file}:${item.site.semanticPath.join('\u0000')}:${item.site.fingerprint}`;
113				if (seen.has(key)) return false;
114				seen.add(key);
115				return true;
116			})
117			.sort((a, b) =>
118				`${a.site.file}:${a.site.semanticPath.join('/')}:${a.reason}`.localeCompare(
119					`${b.site.file}:${b.site.semanticPath.join('/')}:${b.reason}`,
120				),
121			);
122	}
123	
124	function moduleClosure(seed: Module, direction: 'dependencies' | 'dependents'): Set<Module> {
125		const modules = new Set<Module>([seed]);
126		const queue = [seed];
127		for (const module of queue)
128			for (const next of module[direction])
129				if (!modules.has(next)) {
130					modules.add(next);
131					queue.push(next);
132				}
133		return modules;
134	}
135	
136	function baseUnresolved(analyzer: Analyzer, relevant: ReadonlySet<Module>): UnresolvedSite[] {
137		const unresolved: UnresolvedSite[] = [];
138		const keys = suppliedInputIndex(analyzer);
139		for (const module of analyzer.modules.values()) {
140			if (!relevant.has(module)) continue;
141			for (const [index, diagnostic] of module.diagnostics.entries())
142				unresolved.push({
143					site: anchorSite(module, undefined, 'parse-diagnostic', index),
144					reason: 'unparsed-file',
145					detail: diagnostic.message,
146				});
147			for (const record of module.imports) {
148				if (record.resolvedModule !== null) continue;
149				const reason = boundaryReason(record.specifier, keys);
150				unresolved.push({
151					site: anchorSite(module, record.node, 'import-boundary'),
152					reason,
153					detail: boundaryDetail('import', record.specifier, reason),
154				});
155			}
156			for (const record of module.exports) {
157				if (record.specifier === null || record.resolvedModule !== null) continue;
158				const reason = boundaryReason(record.specifier, keys);
159				unresolved.push({
160					site: anchorSite(module, record.node, 'export-boundary'),
161					reason,
162					detail: boundaryDetail('export', record.specifier, reason),
163				});
164			}
165		}
166		for (const [index, diagnostic] of analyzer.diagnostics.entries()) {
167			const module = analyzer.module(diagnostic.module);
168			if (module === undefined || !relevant.has(module)) continue;
169			unresolved.push({
170				site: anchorSite(module, undefined, 'link-diagnostic', index),
171				reason: diagnostic.message.includes('ambiguous')
172					? 'ambiguous-definition'
173					: 'unresolved-symbol',
174				detail: diagnostic.message,
175			});
176		}
177		return unresolved;
178	}
179	
180	function namespaceEvidence(
181		analyzer: Analyzer,
182		origin: Symbol,
183	): { results: ReferenceResult[]; unresolved: UnresolvedSite[] } {
184		const results: ReferenceResult[] = [];
185		const unresolved: UnresolvedSite[] = [];
186		for (const module of analyzer.modules.values())
187			for (const record of module.imports) {
188				if (!record.isNamespace || record.local === null || record.resolvedModule === null)
189					continue;
190				for (const reference of record.local.references) {
191					const member = module.parentOf(reference.node) as RichNode | null;
192					if (member?.type !== 'MemberExpression' || member.object !== reference.node)
193						continue;
194					const property = member.property as RichNode;
195					const key = staticMemberKey(member);
196					if (key !== null) {
197						const routes = resolvedSymbolPaths(
198							analyzer,
199							record.resolvedModule,
200							String(key),
201							origin,
202						);
203						for (const route of routes) {
204							let current = member;
205							let remaining = route;
206							while (remaining.length > 0) {
207								const parent = module.parentOf(current) as RichNode | null;
208								if (parent?.type !== 'MemberExpression' || parent.object !== current)
209									break;
210								const nextKey = staticMemberKey(parent);
211								if (nextKey === null || nextKey !== remaining[0]) break;
212								current = parent;
213								remaining = remaining.slice(1);
214							}
215							if (remaining.length > 0) continue;
216							const finalProperty = (current as RichNode).property as
217								| YukuNode
218								| undefined;
219							results.push({
220								site: anchorSite(module, finalProperty ?? property, 'namespace-member'),
221								access: expressionAccess(module, current),
222							});
223						}
224						if (routes.length > 0) continue;
225					}
226					if (
227						key !== null ||
228						exportedSymbolPaths(analyzer, record.resolvedModule, origin).length === 0
