893		analyzer: Analyzer,
894		request: QueryRequest,
895		reason: 'unresolved-symbol' | 'unsupported-syntax',
896		detail: string,
897	): Receipt<T> {
898		return makeReceipt({
899			schema: 'guessless.receipt/v1',
900			state: 'refused',
901			query: request.kind,
902			request,
903			snapshot: analyzerSnapshot(analyzer),
904			results: [],
905			reason,
906			detail,
907		});
908	}
909	
910	function resolveOrRefuse(
911		analyzer: Analyzer,
912		request: QueryRequest,
913		anchor: SymbolAnchor,
914	): Symbol | Receipt<never> {
915		return (
916			resolveSymbolAnchor(analyzer.modules, anchor) ??
917			refuse(
918				analyzer,
919				request,
920				'unresolved-symbol',
921				'The anchor is missing, changed, deleted, or ambiguous; resolution fails closed.',
922			)
923		);
924	}
925	
926	export function definitionOf(analyzer: Analyzer, anchor: SymbolAnchor): Receipt<SymbolAnchor> {
927		const request = { kind: 'definitionOf', target: anchor } as const;
928		const symbol = resolveOrRefuse(analyzer, request, anchor);
929		if (!('module' in symbol)) return symbol;
930		const definition = analyzer.definitionOf(symbol);
931		const relevant = moduleClosure(symbol.module, 'dependencies');
932		if (definition?.symbol === null || definition === null)
933			return finish(
934				analyzer,
935				request,
936				[],
937				[
938					...baseUnresolved(analyzer, relevant),
939					{
940						site: anchor,
941						reason: 'unresolved-symbol',
942						detail: 'Yuku could not prove one defining symbol.',
943					},
944				],
945			);
946		return finish(
947			analyzer,
948			request,
949			[anchorSymbol(definition.symbol)],
950			baseUnresolved(analyzer, relevant),
951		);
952	}
953	
954	export function referencesOf(
955		analyzer: Analyzer,
956		anchor: SymbolAnchor,
957		mode: 'all' | 'reads' | 'writes' = 'all',
958	): Receipt<ReferenceResult> {
959		const query = mode === 'all' ? 'referencesOf' : mode === 'reads' ? 'readsOf' : 'writesOf';
960		const request = { kind: query, target: anchor } as const;
961		const symbol = resolveOrRefuse(analyzer, request, anchor);
962		if (!('module' in symbol)) return symbol;
963		const origin = analyzer.definitionOf(symbol)?.symbol ?? symbol;
964		const results = analyzer.referencesOf(origin).map(({ module, reference }) => ({
965			site: anchorSite(module, reference.node, 'reference'),
966			access: referenceAccess(reference),
967		}));
968		const namespace = namespaceEvidence(analyzer, origin);
969		results.push(...namespace.results);
970		results.push(...transportedImportEvidence(analyzer, origin));
971		const filtered = results.filter(
972			(result) =>
973				mode === 'all' ||
974				(mode === 'reads' ? result.access !== 'write' : result.access !== 'read'),
975		);
976		const relevant = moduleClosure(origin.module, 'dependents');
977		// A supplied input whose specifiers failed to link never enters the
978		// dependents closure, so its reference sites are invisible to the walk
979		// above. Name every such file: absence from results must never be silent.
980		return finish(analyzer, request, filtered, [
981			...baseUnresolved(analyzer, relevant),
982			...unlinkedInputSites(analyzer, relevant),
983			...namespace.unresolved,
984			...propertyAliasGaps(analyzer, origin),
985		]);
986	}
987	
988	export function exportedNames(module: Module): Receipt<ExportResult> {
989		const relevant = moduleClosure(module, 'dependencies');
990		return finish(
991			module.analyzer,
992			{ kind: 'exportedNames', file: module.path },
993			module
994				.exportedNames()
995				.map((name) => ({ name, module: anchorSite(module, undefined, 'exports') })),
996			baseUnresolved(module.analyzer, relevant),
997		);
998	}
999	
1000	function functionNode(symbol: Symbol): YukuNode | undefined {
1001		for (const declaration of symbol.declarations) {
1002			const parent = symbol.module.parentOf(declaration) as RichNode | null;
1003			if (parent !== null && ['FunctionDeclaration', 'FunctionExpression'].includes(parent.type))
1004				return parent;
1005			if (
1006				parent?.type === 'VariableDeclarator' &&
1007				parent.init !== undefined &&
1008				['FunctionExpression', 'ArrowFunctionExpression'].includes(parent.init.type)
1009			)
1010				return parent.init;
1011		}
1012		return undefined;
1013	}
1014	
1015	function isWithin(module: Module, child: YukuNode, ancestor: YukuNode): boolean {
1016		let current: YukuNode | null = child;
1017		while (current !== null) {
1018			if (current === ancestor) return true;
1019			current = module.parentOf(current);
1020		}
1021		return false;
1022	}
1023	
1024	export function capturesOf(analyzer: Analyzer, anchor: SymbolAnchor): Receipt<CaptureResult> {
1025		const request = { kind: 'capturesOf', target: anchor } as const;
1026		const symbol = resolveOrRefuse(analyzer, request, anchor);
1027		if (!('module' in symbol)) return symbol;
1028		const node = functionNode(symbol);
1029		if (node === undefined)
1030			return refuse(
1031				analyzer,
1032				request,
1033				'unsupported-syntax',
1034				'The anchored symbol is not backed by a function node.',
1035			);
1036		const results = symbol.module.capturesOf(node).map((capture) => ({
1037			symbol: anchorSymbol(capture.symbol),
1038			references: capture.references.map((reference) =>
1039				anchorSite(symbol.module, reference.node, 'capture-reference'),
1040			),
1041			isWritten: capture.isWritten,
1042		}));
1043		const unresolved = baseUnresolved(analyzer, new Set([symbol.module]));
1044		for (const reference of symbol.module.unresolvedReferences)
1045			if (isWithin(symbol.module, reference.node, node))
1046				unresolved.push({
1047					site: anchorSite(symbol.module, reference.node, 'unresolved-capture'),
1048					reason: 'unresolved-symbol',
1049					detail: `Unresolved/global '${reference.name}' is a capture boundary.`,
1050				});
1051		return finish(analyzer, request, results, unresolved);
1052	}
1053	
1054	export function resolveBinding(
1055		analyzer: Analyzer,
1056		module: Module,
1057		name: string,
1058		space: Space = 'value',
1059		from?: Scope,
1060		scopeAnchor: SymbolAnchor | null = null,
1061	): Receipt<SymbolAnchor> {
1062		const request = {
1063			kind: 'resolveBinding',
1064			file: module.path,
1065			name,
1066			space,
1067			scope: scopeAnchor,
1068		} as const;
1069		const symbol = module.resolve(name, from, space);
1070		if (symbol !== null && symbol.module !== module)
1071			return refuse(
1072				analyzer,
1073				request,
1074				'unresolved-symbol',
1075				'The resolved binding belongs to a different module; resolution fails closed.',
1076			);
1077		return finish(
1078			analyzer,
1079			request,
1080			symbol === null ? [] : [anchorSymbol(symbol)],
1081			baseUnresolved(analyzer, new Set([module])),
1082		);
1083	}
