385	/**
386	 * One analyzed source file: its AST, per-file semantics, and module
387	 * records. Created by {@link Analyzer.addFile}. All queries are local
388	 * (no native calls).
389	 */
390	interface Module {
391	  readonly analyzer: Analyzer;
392	  readonly path: string;
393	  readonly source: string;
394	
395	  /**
396	   * The ESTree / TypeScript-ESTree program. Lazily decoded. Nodes are
397	   * identity-shared with every semantic query result.
398	   *
399	   * Nodes are plain mutable objects: edit them in place, mutate them
400	   * during a walk with {@link WalkContext.replace} and friends, and
401	   * print the result with `yuku-codegen`. Semantic tables stay a
402	   * snapshot of the parsed source and do not track mutations.
403	   */
404	  readonly ast: Program;
405	  /** Syntax and semantic diagnostics for this file. */
406	  readonly diagnostics: Diagnostic[];
407	  /** Every comment in source order. */
408	  readonly comments: Comment[];
409	
410	  /** Every lexical scope; index is the scope id. `scopes[0]` is global. */
411	  readonly scopes: Scope[];
412	  /** The scope top-level code runs in: module scope, or global for scripts. */
413	  readonly rootScope: Scope;
414	  /** Every declared symbol; index is the symbol id. */
415	  readonly symbols: Symbol[];
416	  /** Every identifier reference in source order; index is the reference id. */
417	  readonly references: Reference[];
418	  /** References resolving to no binding: globals and free names. */
419	  readonly unresolvedReferences: Reference[];
420	
421	  /**
422	   * The symbol a node refers to: its own symbol for a declaration
423	   * identifier, the resolved symbol for a reference identifier. Null
424	   * for nodes that are neither, or for unresolved references.
425	   */
426	  symbolOf(node: Node): Symbol | null;
427	  /** The reference recorded for an identifier node, or null. */
428	  referenceOf(node: Node): Reference | null;
429	  /**
430	   * The innermost scope whose extent contains `node`, or the module's
431	   * root scope for a node not produced by this module's analysis.
432	   */
433	  scopeOf(node: Node): Scope;
434	  /**
435	   * The node that structurally contains `node`. Null at the program
436	   * root and for a node not part of this module's AST. Lets you walk
437	   * upward from a node you already hold, with no ancestor stack.
438	   */
439	  parentOf(node: Node): Node | null;
440	  /**
441	   * Walks the scope chain from `from` (default: the root scope) to
442	   * find the nearest binding of `name` visible in `space` (default:
443	   * `"value"`, resolving like runtime code). A binding outside the
444	   * space does not shadow, the walk keeps going. `"any"` matches by
445	   * name alone. A value-position `arguments` lookup stops at the
446	   * first non-arrow function or static block, where the implicit
447	   * arguments object shadows any outer binding of that name.
448	   */
449	  resolve(name: string, from?: Scope, space?: Space): Symbol | null;
450	  /**
451	   * The free variables of a function or arrow: every binding referenced
452	   * inside it (nested closures included, value positions only) that is
453	   * declared outside it. Shadowing- and alias-correct, because it rides
454	   * the resolved reference table.
455	   *
456	   * Only bindings count: `this`, `arguments`, and unresolved/global
457	   * names carry no symbol and never appear. Module-scope and import
458	   * bindings count like any other outer binding; filter on the
459	   * symbol's scope to narrow.
460	   *
461	   * Throws when `node` is not a function of this module's AST.
462	   */
463	  capturesOf(node: Node): Capture[];
464	  /**
465	   * Every name this module exports, directly or through `export *`
466	   * chains (the spec's GetExportedNames). Ambiguous star names are
467	   * included; `"default"` never crosses an `export *` boundary. Links
468	   * on demand.
469	   */
470	  exportedNames(): string[];
471	
472	  /**
473	   * Walks the AST (or the subtree under `root`) with semantic context.
474	   * Scope information is replayed from the native scope tree, so
475	   * non-scope nodes pay a single type lookup and nothing else.
476	   */
477	  walk(visitors: Visitors, root?: Node): void;
478	
479	  /**
480	   * The async counterpart of {@link Module.walk}: identical traversal
481	   * order and mutation semantics, with every handler awaited before
482	   * the walk moves on.
483	   */
484	  walkAsync(visitors: AsyncVisitors, root?: Node): Promise<void>;
485	
486	  /** Collects every node of the given type(s), in source order. */
487	  findAll<K extends NodeType>(type: K): NodeOfType<K>[];
488	  findAll<K extends NodeType>(types: Iterable<K>): NodeOfType<K>[];
489	
490	  /** Import records, in source order. */
491	  readonly imports: Import[];
492	  /** Export records, in source order. */
493	  readonly exports: Export[];
494	  /** Modules this module imports from. Links on demand. */
495	  readonly dependencies: Module[];
496	  /** Modules that import from this module. Links on demand. */
497	  readonly dependents: Module[];
498	}
499	
500	/** A symbol's defining site, possibly in another module. */
501	interface Definition {
502	  readonly module: Module;
503	  /**
504	   * The defining symbol, or null when the definition is a whole module
505	   * namespace (`import * as ns`, `export * as ns`).
506	   */
507	  readonly symbol: Symbol | null;
508	}
509	
510	/** A cross-module reference, as reported by {@link Analyzer.referencesOf}. */
511	interface ModuleReference {
512	  readonly module: Module;
513	  readonly reference: Reference;
514	}
515	
516	/** Options for {@link analyze}: {@link AddFileOptions} plus the module path. */
517	interface AnalyzeOptions extends AddFileOptions {
518	  /**
519	   * The path recorded on the module, also the default source of
520	   * `lang` and `sourceType`.
521	   * @default "input.js"
522	   */
523	  path?: string;
524	}
525	
526	/**
527	 * Parses and analyzes a single file, the shorthand for one-file
528	 * semantics: scopes, symbols, resolved references, and a semantic
529	 * walk. Cross-file surfaces stay empty, use {@link Analyzer} and
530	 * {@link Analyzer.addFile} for multi-file projects and linking.
531	 *
532	 * ```ts
533	 * const module = analyze(`const x = 1; x;`, { lang: "ts" });
534	 * module.walk({ Identifier(node, ctx) { ctx.symbol; } });
535	 * ```
536	 */
537	declare function analyze(source: string, options?: AnalyzeOptions): Module;
538	
539	/**
540	 * The project: a set of analyzed modules and the links between them.
541	 *
542	 * ```ts
543	 * const analyzer = new Analyzer();
544	 * analyzer.addFile("src/app.tsx", source);
545	 * const sym = analyzer.module("src/app.tsx")!.symbolOf(node);
546	 * const def = sym?.definition();
547	 * ```
548	 */
549	declare class Analyzer {
550	  constructor(options?: AnalyzerOptions);
551	
552	  /**
553	   * Parses and analyzes one file natively, returning its {@link Module}.
554	   * Adding an existing path replaces it and marks the graph for
555	   * relinking.
556	   */
557	  addFile(path: string, source: string, options?: AddFileOptions): Module;
558	  /** Removes a file. Returns whether it existed. */
559	  removeFile(path: string): boolean;
560	  /** The module added under `path`, if any. */
561	  module(path: string): Module | undefined;
562	  /** All modules, keyed by path. */
563	  readonly modules: ReadonlyMap<string, Module>;
564	  /** Graph-level diagnostics. Links on demand. */
565	  readonly diagnostics: LinkDiagnostic[];
566	
567	  /**
568	   * Joins imports to exports across every added module: resolves
569	   * specifiers through the host resolver, populates
570	   * {@link Import.resolvedModule}, {@link Module.dependencies} /
571	   * {@link Module.dependents}, and reports unresolvable or ambiguous
572	   * names. Resolution follows the spec's ResolveExport semantics: a
573	   * name supplied by multiple `export *` declarations through
574	   * different bindings is an error, and `"default"` is never satisfied
575	   * by `export *`.
576	   *
577	   * Calling this is optional: every cross-file surface links on demand
578	   * after files change. Call it explicitly to control when the work
579	   * (and its diagnostics) happen.
580	   */
581	  link(): void;
582	
583	  /**
584	   * Follows import -> export -> re-export chains to the symbol that
585	   * actually defines `symbol`. A null `symbol` in the result means a
586	   * module namespace. Returns null when the chain leaves the added
587	   * file set (external modules), does not resolve, or is ambiguous.
588	   */
589	  definitionOf(symbol: Symbol): Definition | null;
590	
591	  /**
592	   * Every reference to `symbol` across the whole graph: local uses
593	   * plus uses of every import binding that resolves back to it.
594	   */
595	  referencesOf(symbol: Symbol): ModuleReference[];
596	}
597	
598	/** Resolves a {@link SourceLang} from a file path's extension. */
599	declare function langFromPath(path: string): SourceLang;
600	
601	/** Resolves a {@link SourceType} from a file path's extension. */
602	declare function sourceTypeFromPath(path: string): SourceType;
603	
604	export {
605	  analyze,
606	  Analyzer,
607	  SymbolFlags,
608	  langFromPath,
609	  sourceTypeFromPath,
610	  type AddFileOptions,
611	  type AnalyzeOptions,
612	  type AnalyzerOptions,
613	  type AsyncVisitors,
614	  type AsyncWalkHandler,
615	  type AsyncWalkHooks,
616	  type Capture,
617	  type Definition,
618	  type Export,
619	  type Import,
620	  type LinkDiagnostic,
621	  type Module,
622	  type ModuleReference,
623	  type NodeOfType,
624	  type NodeType,
625	  type Reference,
626	  type Scope,
627	  type ScopeKind,
628	  type Space,
629	  type Symbol,
630	  type Visitors,
631	  type WalkContext,
632	  type WalkHandler,
633	  type WalkHooks,
634	};
635

