  type Export,
  type Import,
  type LinkDiagnostic,
  type Module,
  type ModuleReference,
  type NodeOfType,
  type NodeType,
  type Reference,
  type Scope,
  type ScopeKind,
  type Space,
  type Symbol,
  type Visitors,
  type WalkContext,
  type WalkHandler,
  type WalkHooks,
};

