240	function sortRoles(roles: ReadonlySet<SafeChangeRole>): SafeChangeRole[] {
241		return SAFE_CHANGE_ROLES.filter((role) => roles.has(role));
242	}
243	
244	function uniqueAnchors(anchors: readonly SymbolAnchor[]): SymbolAnchor[] {
245		const seen = new Set<string>();
246		return anchors.filter((anchor) => {
247			const key = canonicalize(anchor);
248			if (seen.has(key)) return false;
249			seen.add(key);
250			return true;
251		});
252	}
253	
254	function uniqueUnresolved(items: readonly UnresolvedSite[]): UnresolvedSite[] {
255		const seen = new Set<string>();
256		return [...items]
257			.filter((item) => {
258				const key = `${canonicalize(item.site)}:${item.reason}`;
259				if (seen.has(key)) return false;
260				seen.add(key);
261				return true;
262			})
263			.sort((left, right) =>
264				`${canonicalize(left.site)}:${left.reason}`.localeCompare(
265					`${canonicalize(right.site)}:${right.reason}`,
266				),
267			);
268	}
269	
270	function addImpact(
271		impacts: Map<string, SafeChangeImpactResult>,
272		site: SymbolAnchor,
273		roles: readonly SafeChangeRole[],
274		witness: readonly SymbolAnchor[] = [],
275	): void {
276		const key = canonicalize(site);
277		const previous = impacts.get(key);
278		impacts.set(key, {
279			site,
280			roles: sortRoles(new Set([...(previous?.roles ?? []), ...roles])),
281			witness: uniqueAnchors([...(previous?.witness ?? []), ...witness]),
282		});
283	}
284	
285	function refuse(
286		analyzer: Analyzer,
287		request: Extract<QueryRequest, { kind: 'safeChangeImpact' }>,
288		reason: UnresolvedReason,
289		detail: string,
290	): Receipt<SafeChangeImpactResult> {
291		return makeReceipt({
292			schema: 'guessless.receipt/v1',
293			state: 'refused',
294			query: 'safeChangeImpact',
295			request,
296			snapshot: analyzerSnapshot(analyzer),
297			results: [],
298			reason,
299			detail,
300		});
301	}
302	
303	function resolvedTarget(
304		analyzer: Analyzer,
305		request: Extract<QueryRequest, { kind: 'safeChangeImpact' }>,
306	): { target: SymbolAnchor; unresolved: UnresolvedSite[] } | Receipt<SafeChangeImpactResult> {
307		if (isAnchor(request.target)) {
308			if (resolveSymbolAnchor(analyzer.modules, request.target) === null)
309				return refuse(
310					analyzer,
311					request,
312					'unresolved-symbol',
313					'The target anchor is missing, changed, deleted, or ambiguous.',
314				);
315			return { target: request.target, unresolved: [] };
316		}
317		const selector = request.target;
318		const module = analyzer.module(selector.file);
319		if (module === undefined)
320			return refuse(
321				analyzer,
322				request,
323				'unresolved-symbol',
324				`Module '${selector.file}' is not in the linked set.`,
325			);
326		if (selector.from !== undefined && selector.from.file !== selector.file)
327			return refuse(
328				analyzer,
329				request,
330				'unresolved-symbol',
331				'The selector scope belongs to a different module.',
332			);
333		const from =
334			selector.from === undefined ? null : resolveAnchor(analyzer.modules, selector.from);
335		if (selector.from !== undefined && from === null)
336			return refuse(
337				analyzer,
338				request,
