1	import { readFileSync, readdirSync } from 'node:fs';
2	import { dirname, join } from 'node:path';
3	import { fileURLToPath } from 'node:url';
4	import { expect, test } from 'vitest';
5	import {
6		anchorSite,
7		GuesslessEngine,
8		sha256,
9		type ReferenceResult,
10		type SymbolAnchor,
11	} from '../src/index.ts';
12	
13	const fixtureDir = join(dirname(fileURLToPath(import.meta.url)), 'fixtures/adversarial');
14	type ExpectedQuery = { state: string; request: string; results: string[]; unresolved: string[] };
15	type Truth = Record<string, ExpectedQuery | string[]>;
16	
17	function assertUniqueExact(actual: string[], expected: string[], label: string): void {
18		expect(new Set(actual).size, `${label} contains duplicate identities`).toBe(actual.length);
19		expect(new Set(expected).size, `${label} ground truth contains duplicate identities`).toBe(
20			expected.length,
21		);
22		expect([...actual].sort()).toEqual([...expected].sort());
23	}
24	
25	function assertResolvable(
26		engine: GuesslessEngine,
27		anchors: readonly SymbolAnchor[],
28		label: string,
29	): void {
30		for (const anchor of anchors)
31			expect(
32				engine.resolve(anchor),
33				`${label} is unresolvable: ${JSON.stringify(anchor)}`,
34			).not.toBeNull();
35	}
36	
37	test('every query request, result citation, and unresolved citation matches exact planted identity', () => {
38		const engine = new GuesslessEngine();
39		for (const name of readdirSync(fixtureDir).filter((file) => /\.(?:js|jsx|ts|tsx)$/.test(file)))
40			engine.addFile(name, readFileSync(join(fixtureDir, name), 'utf8'));
41		engine.link();
42		const truth = JSON.parse(readFileSync(join(fixtureDir, 'ground-truth.json'), 'utf8')) as Truth;
43		const target = engine.anchor('definitions.ts', 'target')!;
44		const queries = {
45			definitionOf: engine.definitionOf(target),
46			referencesOf: engine.referencesOf(target),
47			readsOf: engine.readsOf(target),
48			writesOf: engine.writesOf(target),
49			exportedNames: engine.exportedNames('export-star.ts'),
50			capturesOf: engine.capturesOf(engine.anchor('definitions.ts', 'makeClosure')!),
51			resolveBinding: engine.resolveBinding('definitions.ts', 'target'),
52			reachableFrom: engine.reachableFrom(
53				engine.anchor('reachability-entry.ts', 'dependencyEntry')!,
54			),
55			reaches: engine.reaches(engine.anchor('reachability-entry.ts', 'partialEntry')!),
56		};
57	
58		for (const [name, receipt] of Object.entries(queries)) {
59			const expected = truth[name] as ExpectedQuery;
60			expect(receipt.state).toBe(expected.state);
61			expect(engine.verify(receipt)).toBe(true);
62			expect(sha256(receipt.request)).toBe(expected.request);
63			const results =
64				name === 'referencesOf' || name === 'readsOf' || name === 'writesOf'
65					? receipt.results.map(
66							(item) =>
67								`${sha256((item as { site: SymbolAnchor }).site)}:${(item as { access: string }).access}`,
68						)
69					: name === 'exportedNames'
70						? receipt.results.map(
71								(item) =>
72									`${sha256((item as { module: SymbolAnchor }).module)}:${(item as { name: string }).name}`,
73							)
74						: name === 'capturesOf'
75							? receipt.results.map((item) => {
76									const capture = item as {
77										symbol: SymbolAnchor;
78										references: SymbolAnchor[];
79										isWritten: boolean;
80									};
81									return `${sha256(capture.symbol)}:${capture.references.map(sha256).join(',')}:${capture.isWritten}`;
82								})
83							: name === 'reachableFrom' || name === 'reaches'
84								? receipt.results.map((item) => {
85										const result = item as {
86											symbol: SymbolAnchor;
87											witness: SymbolAnchor[];
88										};
89										return `${sha256(result.symbol)}:${result.witness.map(sha256).join(',')}`;
90									})
91								: receipt.results.map((item) => sha256(item));
92			assertUniqueExact(results, expected.results, `${name} results`);
93			if (receipt.state === 'partial')
94				assertUniqueExact(
95					receipt.unresolved.map((item) => `${sha256(item.site)}:${item.reason}`),
96					expected.unresolved,
97					`${name} unresolved`,
98				);
99			else expect(expected.unresolved).toEqual([]);
100		}
101	
102		assertResolvable(engine, queries.definitionOf.results, 'definition result');
103		for (const name of ['referencesOf', 'readsOf', 'writesOf'] as const) {
104			assertResolvable(
105				engine,
106				queries[name].results.map((item) => item.site),
107				`${name} result`,
108			);
109			if (queries[name].state === 'partial')
110				assertResolvable(
111					engine,
112					queries[name].unresolved.map((item) => item.site),
113					`${name} unresolved`,
114				);
115		}
116		assertResolvable(
117			engine,
118			queries.exportedNames.results.map((item) => item.module),
119			'export module',
120		);
121		for (const capture of queries.capturesOf.results) {
122			assertResolvable(engine, [capture.symbol], 'capture symbol');
123			assertResolvable(engine, capture.references, 'capture reference');
124		}
125		assertResolvable(engine, queries.resolveBinding.results, 'binding result');
126		for (const name of ['reachableFrom', 'reaches'] as const)
127			for (const result of queries[name].results) {
128				assertResolvable(engine, [result.symbol], `${name} symbol`);
129				assertResolvable(engine, result.witness, `${name} witness`);
